package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;
public final class CatalogCart{
 private static final WeakHashMap<AlertDialog,State> sessions=new WeakHashMap<>();
 private static final class State{final LinkedHashMap<String,JSONObject> items=new LinkedHashMap<>();volatile boolean busy;Button button;}
 private static String manage(Activity a,JSONObject req)throws Exception{return(String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,"editor_add",req.toString());}
 public static void attach(Activity a,AlertDialog parent){State s=sessions.get(parent);if(s==null){s=new State();sessions.put(parent,s);final State state=s;LinearLayout title=new LinearLayout(a);title.setPadding(16,12,16,8);TextView label=new TextView(a);label.setText("Player Catalogue");label.setTextColor(0xffeffaff);label.setTextSize(18);title.addView(label,new LinearLayout.LayoutParams(0,-2,1));s.button=new Button(a);s.button.setAllCaps(false);title.addView(s.button);s.button.setOnClickListener(v->review(a,state));parent.setCustomTitle(title);}s.button.setText("Cart ("+s.items.size()+")");}
 public static void select(Activity a,JSONObject card,AlertDialog parent){attach(a,parent);State s=sessions.get(parent);if(s.busy)return;s.items.put(card.optString("id"),card);s.button.setText("Cart ("+s.items.size()+")");Toast.makeText(a,"Added to cart",Toast.LENGTH_SHORT).show();}
 private static void review(Activity a,State s){if(s.busy)return;ArrayList<String> ids=new ArrayList<>(s.items.keySet());String[] names=new String[ids.size()];for(int i=0;i<ids.size();i++){JSONObject p=s.items.get(ids.get(i));names[i]=p.optString("name",ids.get(i))+" · "+ids.get(i);}AlertDialog d=new AlertDialog.Builder(a).setTitle("Selected players · "+ids.size()).setItems(names,(x,i)->{if(!s.busy){s.items.remove(ids.get(i));s.button.setText("Cart ("+s.items.size()+")");}}).setNegativeButton("Keep selecting",null).setPositiveButton("Add to Storage",null).create();d.show();ResponsiveUi.fit(a,d);d.getButton(-1).setEnabled(!s.busy&&!ids.isEmpty());d.getButton(-1).setOnClickListener(v->{s.busy=true;s.button.setEnabled(false);d.getButton(-1).setEnabled(false);new Thread(()->{String failure=null;int added=0;for(String id:ids){try{JSONObject req=new JSONObject().put("card_id",Long.parseLong(id)).put("destination","inventory");JSONObject reply=new JSONObject(manage(a,req));if(reply.has("error"))throw new Exception(reply.optString("error"));if(!reply.optBoolean("changed",false)||reply.optJSONObject("player")==null||!reply.optJSONObject("player").optString("id").equals(id))throw new Exception("Storage receipt did not confirm this card");if(reply.has("result")&&!reply.optString("result").equals("NOERR"))throw new Exception(reply.optString("result"));s.items.remove(id);added++;}catch(Exception e){failure=String.valueOf(e.getCause()==null?e.getMessage():e.getCause().getMessage());break;}}final String error=failure;final int count=added;a.runOnUiThread(()->{s.busy=false;s.button.setEnabled(true);s.button.setText("Cart ("+s.items.size()+")");d.dismiss();if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Storage · "+count+" added").setMessage(error==null?"Players added. Continue selecting in this catalogue.":"Remaining selections kept. "+error).setPositiveButton("OK",null).show();});},"CatalogueCartAdd").start();});}
}
